#include "half.hpp"
#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

using half_float::half;

// Vector types for CPU codegen.
// The C codegen emits vector pointer casts like *(float4*)(ptr + offset)
// and broadcast expressions like ((float4)(v, v, v, v)) where the comma
// expression evaluates to a single value, requiring a one-arg constructor.
template <typename T, int N> struct vec_type {
  T data[N];
  vec_type() = default;
  explicit vec_type(T v) {
    for (int i = 0; i < N; i++)
      data[i] = v;
  }
  template <typename U> explicit vec_type(const vec_type<U, N> &other) {
    for (int i = 0; i < N; i++)
      data[i] = static_cast<T>(other.data[i]);
  }
  vec_type operator+(const vec_type &o) const {
    vec_type r;
    for (int i = 0; i < N; i++)
      r.data[i] = data[i] + o.data[i];
    return r;
  }
  vec_type operator-(const vec_type &o) const {
    vec_type r;
    for (int i = 0; i < N; i++)
      r.data[i] = data[i] - o.data[i];
    return r;
  }
  vec_type operator*(const vec_type &o) const {
    vec_type r;
    for (int i = 0; i < N; i++)
      r.data[i] = data[i] * o.data[i];
    return r;
  }
  vec_type operator/(const vec_type &o) const {
    vec_type r;
    for (int i = 0; i < N; i++)
      r.data[i] = data[i] / o.data[i];
    return r;
  }
  // Compound assignment — avoids temporary vec_type objects
  vec_type &operator+=(const vec_type &o) {
    for (int i = 0; i < N; i++)
      data[i] += o.data[i];
    return *this;
  }
  vec_type &operator-=(const vec_type &o) {
    for (int i = 0; i < N; i++)
      data[i] -= o.data[i];
    return *this;
  }
  vec_type &operator*=(const vec_type &o) {
    for (int i = 0; i < N; i++)
      data[i] *= o.data[i];
    return *this;
  }
  vec_type &operator/=(const vec_type &o) {
    for (int i = 0; i < N; i++)
      data[i] /= o.data[i];
    return *this;
  }
};

